const { copyFileSync, existsSync } = require('fs');
const path = require('path');
const { getParameters } = require('../environment');
var allure = require('allure-commandline');

let { portNumber, report_folder } = getParameters();
let reportFolder = report_folder || 'report';
reportFolder = path.resolve(process.cwd(), reportFolder);

//Allure commands do not work with paths containing spaces. Adding quotes works with command line but not run from a js file.
const relativeReportFolder = path.relative(process.cwd(), reportFolder);

try {
    if (!existsSync(`${reportFolder}/allure-results`)) {
        throw new Error('Allure-results folder does not exist.');
    }
    //cp command only works on Unix/bash consoles! Changed to use fs command to make it compatible with all OS/consoles
    const generation = allure([
        'generate',
        `${relativeReportFolder}/allure-results`,
        '-c',
        '-o',
        `${relativeReportFolder}/allure-report`,
    ]);
    generation.on('exit', function (exitCode) {
        console.log('Generation is finished with code:', exitCode);
        copyFileSync(
            path.resolve(__dirname, '../../', '.allure/styles_edited.css'),
            `${reportFolder}/allure-report/styles.css`,
        );
        copyFileSync(path.resolve(__dirname, '../../', '.allure/app.js'), `${reportFolder}/allure-report/app.js`);
        allure(['open', `${relativeReportFolder}/allure-report`, '-p', `${portNumber}`]);
    });
} catch (error) {
    console.log(error);
}
